public class Main {
    static int[] countSmaller(int[] nums) {
        int n = nums.length;
        int[] counts = new int[n];
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (nums[j] < nums[i]) counts[i]++;
            }
        }
        return counts;
