public class Main {
    static int[] counts;
    static int[] nums;

    static int[] mergeSort(int[] idxArr) {
        if (idxArr.length <= 1) return idxArr;

        int mid = idxArr.length / 2;
        int[] left = mergeSort(Arrays.copyOfRange(idxArr, 0, mid));
        int[] right = mergeSort(Arrays.copyOfRange(idxArr, mid, idxArr.length));

        int rightCount = 0;
        int[] merged = new int[idxArr.length];
        int li = 0, ri = 0, idx = 0;
        while (li < left.length && ri < right.length) {
            if (nums[right[ri]] < nums[left[li]]) {
                rightCount++;
                merged[idx++] = right[ri++];
            } else {
                counts[left[li]] += rightCount;
                merged[idx++] = left[li++];
            }
        }
        while (li < left.length) {
            counts[left[li]] += rightCount;
            merged[idx++] = left[li++];
        }
        while (ri < right.length) merged[idx++] = right[ri++];
        return merged;
    }

    static int[] countSmaller(int[] input) {
        nums = input;
        int n = nums.length;
        counts = new int[n];
        int[] indices = new int[n];
        for (int i = 0; i < n; i++) indices[i] = i;
        mergeSort(indices);
        return counts;
    }

