#include <bits/stdc++.h>
using namespace std;

vector<int> counts;
vector<int> nums;

vector<int> mergeSort(vector<int>& idxArr) {
    if (idxArr.size() <= 1) return idxArr;

    int mid = idxArr.size() / 2;
    vector<int> leftHalf(idxArr.begin(), idxArr.begin() + mid);
    vector<int> rightHalf(idxArr.begin() + mid, idxArr.end());
    vector<int> left = mergeSort(leftHalf);
    vector<int> right = mergeSort(rightHalf);

    int rightCount = 0;
    vector<int> merged;
    int li = 0, ri = 0;
    while (li < (int)left.size() && ri < (int)right.size()) {
        if (nums[right[ri]] < nums[left[li]]) {
            rightCount++;
            merged.push_back(right[ri++]);
        } else {
            counts[left[li]] += rightCount;
            merged.push_back(left[li++]);
        }
    }
    while (li < (int)left.size()) {
        counts[left[li]] += rightCount;
        merged.push_back(left[li++]);
    }
    while (ri < (int)right.size()) merged.push_back(right[ri++]);
    return merged;
}

vector<int> countSmaller(vector<int>& input) {
    nums = input;
    int n = nums.size();
    counts.assign(n, 0);
    vector<int> indices(n);
    for (int i = 0; i < n; i++) indices[i] = i;
    mergeSort(indices);
    return counts;
}

int main() {
    vector<int> nums1 = {5, 2, 6, 1};
    for (int x : countSmaller(nums1)) cout << x << " ";
    cout << endl;
    vector<int> nums2 = {-1};
    for (int x : countSmaller(nums2)) cout << x << " ";
    cout << endl;
    return 0;
}
